{
  "formular": "Austrittsmeldung (Nachbildung nach Vorbild SWICA)",
  "felder": [
    {
      "feld": "Nachname",
      "vorgabe": "Der Nachname der versicherten Person muss vollständig und korrekt angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Vorname",
      "vorgabe": "Der Vorname der versicherten Person muss vollständig und korrekt angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Geburtsdatum",
      "vorgabe": "Das exakte Geburtsdatum (TT.MM.JJJJ) muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Nationalität",
      "vorgabe": "Die Nationalität der versicherten Person muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Versicherten-Nr.",
      "vorgabe": "Die eindeutige Versichertennummer der aktuellen Versicherung muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Aufenthaltsbewilligung",
      "vorgabe": "Falls vorhanden, muss die Nummer oder Art der Aufenthaltsbewilligung angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Beruf",
      "vorgabe": "Der ausgeübte Beruf muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Strasse/Nr.",
      "vorgabe": "Die vollständige Strassenadresse inklusive Hausnummer muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "PLZ",
      "vorgabe": "Die korrekte Postleitzahl des Wohnorts muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Wohnort",
      "vorgabe": "Der vollständige Wohnort (Ort) muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Telefon",
      "vorgabe": "Eine gültige Telefonnummer für Rückfragen muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "E-Mail",
      "vorgabe": "Eine gültige E-Mail-Adresse muss angegeben werden, falls eine Kommunikation per E-Mail gewünscht ist.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Geschlecht",
      "vorgabe": "Das Geschlecht muss mit einem Häkchen markiert werden (männlich oder weiblich).",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Erklärung der versicherten Person",
      "vorgabe": "Es muss eindeutig angegeben werden, ob die Person austritt oder bereits ausgetreten ist (z. B. „Ich werde aus der Firma austreten“ oder „Ich bin aus der Firma ausgetreten“).",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Austrittsdatum",
      "vorgabe": "Das genaue Datum des Austritts aus der Firma muss im Format TT.MM.JJJJ angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Interesse an Weiterführung",
      "vorgabe": "Es muss angekreuzt werden, ob eine unverbindliche Offerte für die Weiterführung der Versicherung gewünscht wird oder ob auf das Recht zur Weiterführung verzichtet wird.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Unterschrift",
      "vorgabe": "Die unterschreibende Person muss ihre Unterschrift handschriftlich leisten.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Datum",
      "vorgabe": "Das Datum der Unterzeichnung muss im Format TT.MM.JJJJ angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    }
  ]
}
